import{_ as n,C as r,o as p,c,a3 as a,E as t}from"./chunks/framework.BZCmpA0A.js";const k=JSON.parse('{"title":"04 · 行程管理","description":"","frontmatter":{},"headers":[],"relativePath":"topics/processes.md","filePath":"topics/processes.md","lastUpdated":1794124004000}'),o={name:"topics/processes.md"};function l(i,e,d,h,u,m){const s=r("MermaidDiagram");return p(),c("div",null,[e[0]||(e[0]=a('<h1 id="_04-·-行程管理" tabindex="-1">04 · 行程管理 <a class="header-anchor" href="#_04-·-行程管理" aria-label="Permalink to &quot;04 · 行程管理&quot;">​</a></h1><p>程式是一份指令與資料；Process（行程）是這份程式正在執行的一次實例。兩個行程可以執行同一份程式，卻擁有不同 PID、暫存器與私有資料。</p><h2 id="pcb-保存什麼" tabindex="-1">PCB 保存什麼 <a class="header-anchor" href="#pcb-保存什麼" aria-label="Permalink to &quot;PCB 保存什麼&quot;">​</a></h2><p>原始碼：<a href="https://github.com/johnson931128/WUWAOS/blob/main/kernel/proc/process.h" target="_blank" rel="noreferrer">kernel/proc/process.h（GitHub）</a>。</p><p><code>ProcessControlBlock</code> 就是 PCB（行程控制區塊），<code>processes[16]</code> 是目前行程表。<code>page_table</code> 找到私有位址空間，<code>frame</code> 找到暫存器保存狀態；<code>event_wait</code> 記錄 source generation/sequence、deadline 與完成結果。阻塞讀寫在原 process kernel stack 上恢復後重試，不把使用者 buffer 指標交給 scheduler poller。</p><p><code>kernel/proc/gate.c</code> 的 owner-aware recursive Gate 由 PCB/PID 記錄持有者與深度，等待者以 event sequence 防止漏喚醒。FS、VM、各 OFD 與各 pipe 使用不同 scope；runtime caller 可在等待 Gate 時讓出核心 stack，scheduler/UI poll 不可睡眠。新 PCB 保留 <code>PROCESS_NEW</code> slot 等頁表/frame 初始化完成，<code>pcb</code> 對 null frame 顯示 initializing。</p><p><code>ready_next</code> 是指向下一個 Ready PCB 的指標，不是另一份行程副本。每個核心堆疊有 16 KiB 可用空間，下方另留一頁 4 KiB guard，從共用核心頁表取消映射；scheduler stack 亦採相同保護。初始化只清可用 stack，不碰未映射 guard。使用者頁面則由 VM 按需要配置。</p><h2 id="核心函式如何暫停與恢復" tabindex="-1">核心函式如何暫停與恢復 <a class="header-anchor" href="#核心函式如何暫停與恢復" aria-label="Permalink to &quot;核心函式如何暫停與恢復&quot;">​</a></h2><p>現在 PCB 另有 <code>KernelContext</code>（核心呼叫上下文），與 <code>TrapFrame</code>（使用者陷阱保存狀態）分開。前者保存核心的 ra（返回位置）、sp（堆疊位置）與 s0～s11（呼叫後必須保留的暫存器）；後者保存使用者暫存器與返回使用者模式所需的控制狀態。</p><p>原始碼：<a href="https://github.com/johnson931128/WUWAOS/blob/main/arch/riscv/swtch.S" target="_blank" rel="noreferrer">swtch.S</a>／<a href="https://github.com/johnson931128/WUWAOS/blob/main/arch/riscv/context.h" target="_blank" rel="noreferrer">context.h</a>。RV64 使用 sd（儲存 64-bit）與 ld（載入 64-bit）；最後 ret 使用恢復後的返回位置。這是函式呼叫邊界的保存，不是任意指令位置的完整中斷保存。</p>',10)),t(s,{source:`flowchart TD
    A[行程 A：核心中的 sleep 或阻塞 I/O] --> B[設 Waiting，保存核心上下文]
    B --> C[切到排程器的獨立堆疊]
    C --> D[派發其他就緒行程]
    D --> E[A 的事件完成，改回 Ready]
    E --> F[再次選中 A，恢復其核心堆疊]
    F --> G[從原函式繼續，正常回傳 syscall 結果]
`}),e[1]||(e[1]=a(`<p>每個行程保留自己的核心 C 呼叫堆疊，所以 wait 被喚醒後能接著檢查子行程並回收，read 被喚醒後能接著回傳真正讀取長度。排程器另有 16 KiB 堆疊，能安全回收已退出行程；不需要在某個退出行程的堆疊上挑選下一個。</p><p>新行程沒有舊核心呼叫位置，第一次切入走 first_run，再由 user_enter／sret 進使用者程式。fork 子行程使用新的核心上下文，沒有複製父的核心呼叫堆疊。pcb 的 kernel_context_sp／ra 是上次保存的值，Running 時可能不是目前硬體值。</p><p>完整設計與驗收見 <a href="./../SPEC-16-kernel-context.html">Spec 16</a>。這提供後續 Mutex（互斥鎖）與 Semaphore（號誌）的阻塞基礎；核心內仍未開啟強制搶占。</p><h2 id="狀態怎麼走" tabindex="-1">狀態怎麼走 <a class="header-anchor" href="#狀態怎麼走" aria-label="Permalink to &quot;狀態怎麼走&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Unused → New → Ready → Running</span></span>
<span class="line"><span>                 ↑        ├─ yield → Ready</span></span>
<span class="line"><span>                 │        ├─ sleep／wait／阻塞 I/O → Waiting</span></span>
<span class="line"><span>                 └─ 喚醒 ─┘</span></span>
<span class="line"><span>Running／Ready／Waiting → exit／kill → Zombie → wait → Unused</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>Zombie（已退出、待回收）仍保留結束結果與資源，讓父行程能透過 wait 取得結果。它已不再執行，也不在 Ready queue（就緒佇列）裡。</p><p><code>kill</code> 遇到仍在 syscall/fault/timer kernel call stack 上的目標時，先標記 <code>kill_pending</code>；可取消的 event、channel、child 或 sync wait 會喚醒原 stack 供其 unwind。cancel-defer 保護 cleanup、已提交 Block request 與 VM swap-out 的撤銷／回復範圍，須到裝置完成或確認 reset、釋放 Gate 並完成清理後，才在 trap return 邊界處理 kill。一般不持有 suspended kernel call stack 的目標仍可直接終止；這不是可隨時中斷 DMA 的任意取消機制。</p><p>Guard page 命中且成功進入 C trap handler 時會印 PID／stack 範圍並停機；若 stack 已不足以讓 <code>trap.S</code> 保存 TrapFrame，仍可能再次 fault，尚未設 emergency trap stack。這項保護及本輪取消路徑只完成實作，runtime 驗證為 NOT_RUN。</p><h2 id="建立、複製與替換" tabindex="-1">建立、複製與替換 <a class="header-anchor" href="#建立、複製與替換" aria-label="Permalink to &quot;建立、複製與替換&quot;">​</a></h2><p><code>create_process</code> 取得空 PCB，準備頁表與初始 TrapFrame，成功後才公布 Ready。建立中途失敗就回收不完整空間。</p><p><code>process_fork</code> 複製父行程的使用者內容與已越過 ecall 的暫存器狀態。父 a0 得到子 PID，子 a0 得到 0。核心堆疊不直接複製；常駐頁與已交換資料都取得獨立內容，目前沒有 COW（寫入時複製）。</p><p><code>process_exec</code> 先準備新空間與必要參數，成功後才切換並銷毀舊空間。PID 和父子關係保留，下一次返回使用者模式時從新程式入口開始。</p><h2 id="在-qemu-觀察" tabindex="-1">在 QEMU 觀察 <a class="header-anchor" href="#在-qemu-觀察" aria-label="Permalink to &quot;在 QEMU 觀察&quot;">​</a></h2><p>從新開機開始，逐條輸入：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>fork</span></span>
<span class="line"><span>ps</span></span>
<span class="line"><span>wait 2</span></span>
<span class="line"><span>run worker</span></span>
<span class="line"><span>ps</span></span>
<span class="line"><span>pcb 3</span></span>
<span class="line"><span>wakeup 7</span></span>
<span class="line"><span>wait 3</span></span>
<span class="line"><span>ps</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p>父子應顯示不同的私有 data／stack 值。worker 等待事件通道 7，喚醒後可回收。若先前已建立過行程，請以實際輸出的 PID 取代 2／3；<code>sleep(7)</code> 是等待通道 7，不是睡 7 秒。</p><h2 id="回收與限制" tabindex="-1">回收與限制 <a class="header-anchor" href="#回收與限制" aria-label="Permalink to &quot;回收與限制&quot;">​</a></h2><p>exit 關閉端點並留下 Zombie；wait 取得結果後釋放使用者頁、Swap slots（交換區槽位）、私有頁表及 PCB。孤兒行程另有接管與回收流程。狀態結果寫入父使用者空間失敗時，不會先丟棄 Zombie。</p><p>最多 16 個行程（含 shell），exec 支援內建程式 ID，也支援從路徑載入受限的靜態 RV64 ELF；不支援任意 Linux 執行檔。沒有執行緒與完整作業控制。</p><p>觀念參考：<code>notes/ch3 Process.md</code>。實作脈絡見 <a href="./../SPEC-02-process-lifecycle.html">Spec 02</a>、<a href="./../SPEC.html">Spec 05</a>，目前私有記憶體複製見 <a href="./../SPEC-10-demand-paging.html">Spec 10</a>。</p><h2 id="同步物件" tabindex="-1">同步物件 <a class="header-anchor" href="#同步物件" aria-label="Permalink to &quot;同步物件&quot;">​</a></h2><p>WUWAOS 以自訂核心物件與 syscall 實作 Mutex（互斥鎖）及 Semaphore（計數號誌），不依賴 POSIX。Mutex 確保單一持有者；Semaphore 用計數管理資源。資源不足時行程阻塞，核心在條件改變時喚醒 FIFO 等待者。</p><p>目前單核心、核心內不搶占，這是等待佇列操作不被同時改動的前提。持鎖行程終止或 exec 時，鎖標記為 poisoned（資料可能不一致）；後續取得會回報錯誤。Semaphore 名額不會因持有行程離開自動返還。詳細介面、例外與驗證狀態見 <a href="./../SPEC-22-synchronization.html">Spec 22</a>，<a href="https://github.com/johnson931128/WUWAOS/blob/main/kernel/ipc/sync.c" target="_blank" rel="noreferrer">核心原始碼</a>。</p><p>可以在 QEMU 使用 <code>sync sem create 0</code> 建立初始值為 0 的號誌，再以 <code>syncbg sem wait &lt;id&gt;</code> 啟動等待的子行程。使用 <code>ps</code> 看到 Waiting sync，之後以 <code>sync sem post &lt;id&gt;</code> 喚醒它，再用 <code>wait &lt;pid&gt;</code> 回收。<code>syncbg mutex hold &lt;id&gt;</code> 的子行程持鎖等待通道 7，<code>wakeup 7</code> 使其解鎖並離開；實際編號以畫面顯示為準。<code>wakeup 7</code> 同時喚醒其他等待此通道的行程。</p><h2 id="用-demo-sync-觀察兩個行程" tabindex="-1">用 demo sync 觀察兩個行程 <a class="header-anchor" href="#用-demo-sync-觀察兩個行程" aria-label="Permalink to &quot;用 demo sync 觀察兩個行程&quot;">​</a></h2><p>在 <code>wuwaos/&gt;</code> 輸入 <code>demo sync</code>，shell 父行程會持有 Mutex，建立子行程並顯示 <code>ps</code>。子行程取得鎖並釋放後，再等待初始值為 0 的 Semaphore；父行程顯示第二次 <code>ps</code>，接著發出 post。最後子行程結束並由父行程回收。行程編號每次可能不同。</p><p>此範例用終端輸出展示臨界區域，不是共享記憶體範例。兩次快照前各等待 200 ms，讓子行程有機會執行；快照反映真實狀態，忙碌時不保證剛好看到 Waiting。完成後回收同步物件；若行程欄位不足會顯示錯誤。詳細設計見 <a href="./../SPEC-23-sync-demo.html">Spec 23</a>，原始程式見 <a href="https://github.com/johnson931128/WUWAOS/blob/main/user/shell/sync_demo.c" target="_blank" rel="noreferrer">GitHub</a>。</p>`,27))])}const _=n(o,[["render",l]]);export{k as __pageData,_ as default};
